package org.xingmu.tv;
import android.app.Activity;import android.os.*;import android.content.Intent;import android.view.*;import android.widget.*;import android.text.*;import java.util.*;import java.util.concurrent.*;
public final class LibraryActivity extends Activity {
 private final List<CatalogItem> all=new ArrayList<>(),shown=new ArrayList<>();
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());
 private String section,group="全部",source="全部来源",scope="全部";private GridLayout grid;private TextView count;private EditText search;private WatchStore store;private boolean loaded;private int displayLimit=60;
 private final Runnable filterTask=()->{displayLimit=60;render();};
 @Override public void onCreate(Bundle state){super.onCreate(state);section=getIntent().getStringExtra("section");if(!Arrays.asList("films","domestic","foreign","opera","favourites","history").contains(section)){finish();return;}store=new WatchStore(this);
  LinearLayout root=TvUi.root(this),head=TvUi.row(this);String title=section.equals("opera")?"戏曲频道":section.equals("films")?"网络影视":section.equals("foreign")?"国外直播":section.equals("history")?"最近观看":section.equals("favourites")?"我的收藏":"电视直播";
  head.addView(TvUi.text(this,title,28,TvUi.INK),new LinearLayout.LayoutParams(0,-2,1));Button back=TvUi.button(this,"返回");back.setOnClickListener(v->finish());head.addView(back);root.addView(head);if(section.equals("films")){Button online=TvUi.button(this,"搜索 TVBox 网络影视源");online.setOnClickListener(v->startActivity(new Intent(this,FilmSearchActivity.class)));root.addView(online);}TvUi.gap(this,root,12);
  search=new EditText(this);search.setSingleLine(true);search.setTextColor(TvUi.INK);search.setHintTextColor(TvUi.MUTED);search.setHint("搜索名称、国家、分类或来源");search.setTextSize(18);root.addView(search,new LinearLayout.LayoutParams(-1,TvUi.dp(this,52)));if(state!=null)search.setText(state.getString("query",""));
  HorizontalScrollView filters=new HorizontalScrollView(this);LinearLayout row=TvUi.row(this);filters.addView(row);root.addView(filters);Spinner categories=new Spinner(this),sources=new Spinner(this),scopes=new Spinner(this);row.addView(categories,new LinearLayout.LayoutParams(TvUi.dp(this,170),TvUi.dp(this,52)));row.addView(sources,new LinearLayout.LayoutParams(TvUi.dp(this,190),TvUi.dp(this,52)));row.addView(scopes,new LinearLayout.LayoutParams(TvUi.dp(this,150),TvUi.dp(this,52)));
  count=TvUi.text(this,"正在加载内容…",15,TvUi.MUTED);root.addView(count);TvUi.gap(this,root,10);ScrollView scroll=new ScrollView(this);grid=new GridLayout(this);scroll.addView(grid);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int c){handler.removeCallbacks(filterTask);handler.postDelayed(filterTask,180);}public void afterTextChanged(Editable e){}});
  worker.execute(()->{try{List<CatalogItem> data=new CatalogRepository(this).load();runOnUiThread(()->{if(isDestroyed())return;for(CatalogItem i:data)if(section.equals("history")||section.equals("favourites")||(section.equals("opera")?i.opera():i.section.equals(section)))all.add(i);LinkedHashSet<String> groups=new LinkedHashSet<>(),names=new LinkedHashSet<>();groups.add("全部");names.add("全部来源");for(CatalogItem i:all){groups.add(section.equals("foreign")?i.country:i.category);names.add(i.source);}setup(categories,new ArrayList<>(groups),v->{group=v;displayLimit=60;render();},state==null?null:state.getString("group"));setup(sources,new ArrayList<>(names),v->{source=v;displayLimit=60;render();},state==null?null:state.getString("source"));setup(scopes,Arrays.asList("全部","仅直播放","仅官方入口","仅收藏"),v->{scope=v;displayLimit=60;render();},state==null?null:state.getString("scope"));loaded=true;render();});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed())count.setText("加载失败，请返回设置检查目录");});}});
 }
 private interface Selected{void set(String value);}
 private void setup(Spinner view,List<String> options,Selected selected,String restored){ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,options);view.setAdapter(adapter);if(restored!=null&&options.contains(restored))view.setSelection(options.indexOf(restored));view.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){if(v instanceof TextView)((TextView)v).setTextColor(TvUi.INK);selected.set(options.get(pos));}});}
 @Override protected void onResume(){super.onResume();if(loaded)render();}
 private void render(){if(!loaded)return;shown.clear();List<String> history=store.history();for(CatalogItem i:all){if(section.equals("favourites")&&!store.favourite(i.id))continue;if(section.equals("history")&&!history.contains(i.id))continue;if(scope.equals("仅收藏")&&!store.favourite(i.id))continue;if(scope.equals("仅直播放")&&!i.mode.equals("stream"))continue;if(scope.equals("仅官方入口")&&!i.mode.equals("official"))continue;if(BrowseFilter.matches(i,search.getText().toString(),group,source,section.equals("foreign")))shown.add(i);}if(section.equals("history"))Collections.sort(shown,(a,b)->Integer.compare(history.indexOf(a.id),history.indexOf(b.id)));
  count.setText(shown.size()+" 项 · 长按或菜单键收藏 · 官方入口需在网页中播放");grid.removeAllViews();int width=getResources().getConfiguration().screenWidthDp;int columns=width>=1000?3:width>=600?2:1;grid.setColumnCount(columns);
  if(shown.isEmpty()){TextView empty=TvUi.text(this,section.equals("opera")?"暂无匹配的纯戏曲内容，可在设置中导入授权戏曲目录。":"没有匹配内容，试试清空搜索或更改筛选。",18,TvUi.MUTED);grid.addView(empty);return;}
  for(int n=0;n<Math.min(shown.size(),displayLimit);n++){CatalogItem i=shown.get(n);final int index=n;String label=(store.favourite(i.id)?"★ ":"")+i.title+"\n"+i.category+" · "+i.country+"\n"+(i.mode.equals("official")?"官方入口":"直接播放")+" · "+i.source;Button card=TvUi.button(this,label);card.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);card.setTextSize(18);GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(n/columns),GridLayout.spec(n%columns,1,1f));p.width=0;p.height=TvUi.dp(this,138);p.bottomMargin=TvUi.dp(this,12);if(n%columns>0)p.leftMargin=TvUi.dp(this,12);grid.addView(card,p);
   card.setOnClickListener(v->{ArrayList<String> ids=new ArrayList<>();for(CatalogItem entry:shown)ids.add(entry.id);startActivity(new Intent(this,PlayerActivity.class).putStringArrayListExtra("ids",ids).putExtra("index",index));});Runnable toggle=()->{store.toggle(i.id);card.setText((store.favourite(i.id)?"★ ":"")+i.title+"\n"+i.category+" · "+i.country+"\n"+(i.mode.equals("official")?"官方入口":"直接播放")+" · "+i.source);TvUi.toast(this,store.favourite(i.id)?"已收藏":"已取消收藏");};card.setOnLongClickListener(v->{toggle.run();return true;});card.setOnKeyListener((v,key,event)->{if(key==KeyEvent.KEYCODE_MENU&&event.getAction()==KeyEvent.ACTION_UP){toggle.run();return true;}return false;});
  }
  if(shown.size()>displayLimit){Button more=TvUi.button(this,"显示更多（已显示 "+displayLimit+" / "+shown.size()+"）");GridLayout.LayoutParams params=new GridLayout.LayoutParams(GridLayout.spec((displayLimit+columns-1)/columns),GridLayout.spec(0,columns));params.width=-1;grid.addView(more,params);more.setOnClickListener(v->{int previous=displayLimit;displayLimit+=60;render();if(grid.getChildCount()>previous)grid.getChildAt(previous).requestFocus();});}
 }
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("query",search.getText().toString());out.putString("group",group);out.putString("source",source);out.putString("scope",scope);}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);worker.shutdownNow();super.onDestroy();}
}
